protected void doClose() {
	if (isActive()) {
		AvailabilityChangeEvent.publish(this, ReadinessState.REFUSING_TRAFFIC);
	}
	super.doClose();
	WebServer webServer = this.webServer;
	if (webServer != null) {
		webServer.destroy();
	}
}

